$action=$_GET['action']??'';
if($_SERVER['REQUEST_METHOD']==='POST'&&$action==='triage'){$d=json_decode(file_get_contents('php://input')?:'{}',true)?:[];$problem=trim((string)($d['problem']??''));$services=is_array($d['services']??null)?$d['services']:[];if($problem==='')out(['ok'=>false,'message'=>'Descreva o caso.'],422);$prompt="Escolha até 3 serviços mais adequados. Responda somente JSON {\"ids\":[\"id\"]}. Caso: ".$problem."\nCatálogo: ".json_encode($services,JSON_UNESCAPED_UNICODE);$ch=curl_init('http://127.0.0.1:11434/api/generate');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode(['model'=>'qwen3:14b','prompt'=>$prompt,'stream'=>false,'format'=>'json']),CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>45]);$raw=curl_exec($ch);curl_close($ch);$j=json_decode((string)$raw,true);$answer=json_decode((string)($j['response']??''),true);if(!is_array($answer)||!is_array($answer['ids']??null))out(['ok'=>false,'message'=>'IA local indisponível.'],503);out(['ok'=>true,'ids'=>array_values(array_slice($answer['ids'],0,3))]);}
if($_SERVER['REQUEST_METHOD']==='POST'&&$action==='login'){$d=json_decode(file_get_contents('php://input')?:'{}',true)?:[];$s=$db->prepare('SELECT * FROM users WHERE username=?');$s->execute([trim((string)($d['username']??''))]);$u=$s->fetch(PDO::FETCH_ASSOC);if(!$u||!password_verify((string)($d['password']??''),$u['password_hash']))out(['ok'=>false,'message'=>'Usuário ou senha inválidos.'],401);$_SESSION['cartorio_user']=['id'=>$u['id'],'username'=>$u['username'],'role'=>$u['role']];out(['ok'=>true,'user'=>$_SESSION['cartorio_user']]);}
