if($_SERVER['REQUEST_METHOD']==='GET'&&$action==='me'){out(['ok'=>true,'authenticated'=>!empty($_SESSION['cartorio_user']),'has_users'=>(int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn()>0,'user'=>$_SESSION['cartorio_user']??null]);}
if(in_array($action,['admin_cases','admin_update'],true)&&empty($_SESSION['cartorio_user']))out(['ok'=>false,'message'=>'Autenticação necessária.'],401);
if($_SERVER['REQUEST_METHOD']==='GET'&&$action==='admin_cases'){out(['ok'=>true,'requests'=>$db->query('SELECT * FROM requests ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC)]);}
