if($_SERVER['REQUEST_METHOD']==='POST'&&$action==='admin_update'){$d=json_decode(file_get_contents('php://input')?:'{}',true)?:[];$code=strtoupper(trim((string)($d['code']??'')));$s=$db->prepare('UPDATE requests SET status=COALESCE(NULLIF(?,\'\'),status),assigned_to=COALESCE(NULLIF(?,\'\'),assigned_to),official_amount=COALESCE(?,official_amount),service_amount=COALESCE(?,service_amount) WHERE code=?');$s->execute([(string)($d['status']??''),(string)($d['assigned_to']??''),$d['official_amount']??null,$d['service_amount']??null,$code]);$e=$db->prepare('INSERT INTO events(code,event,detail,username) VALUES(?,?,?,?)');$e->execute([$code,'Atualização','Status/responsável/valores atualizados',$_SESSION['cartorio_user']['username']??'']);out(['ok'=>true]);}
if($_SERVER['REQUEST_METHOD']==='GET'&&$action==='admin_detail'){$code=strtoupper(trim((string)($_GET['code']??'')));$s=$db->prepare('SELECT * FROM requests WHERE code=?');$s->execute([$code]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)out(['ok'=>false,'message'=>'Ticket não encontrado.'],404);$e=$db->prepare('SELECT * FROM events WHERE code=? ORDER BY id DESC');$e->execute([$code]);$f=$db->prepare('SELECT id,code,filename,created_at FROM documents WHERE code=? ORDER BY id DESC');$f->execute([$code]);out(['ok'=>true,'request'=>$r,'events'=>$e->fetchAll(PDO::FETCH_ASSOC),'documents'=>$f->fetchAll(PDO::FETCH_ASSOC)]);}
if($_SERVER['REQUEST_METHOD']==='POST'&&$action==='admin_document'){if(empty($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)out(['ok'=>false,'message'=>'Arquivo inválido.'],422);$code=strtoupper(trim((string)($_POST['code']??'')));$ext=strtolower(pathinfo($_FILES['file']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['pdf','jpg','jpeg','png'],true)||$_FILES['file']['size']>10*1024*1024)out(['ok'=>false,'message'=>'Aceitos PDF/JPG/PNG até 10 MB.'],422);$folder=$dir.'/uploads';if(!is_dir($folder))mkdir($folder,0750,true);$name=bin2hex(random_bytes(16)).'.'.$ext;$path=$folder.'/'.$name;if(!move_uploaded_file($_FILES['file']['tmp_name'],$path))out(['ok'=>false,'message'=>'Não foi possível guardar o arquivo.'],500);$s=$db->prepare('INSERT INTO documents(code,filename,path) VALUES(?,?,?)');$s->execute([$code,basename($_FILES['file']['name']),$name]);$e=$db->prepare('INSERT INTO events(code,event,detail,username) VALUES(?,?,?,?)');$e->execute([$code,'Documento','Arquivo recebido',$_SESSION['cartorio_user']['username']??'']);out(['ok'=>true]);}
if($_SERVER['REQUEST_METHOD']==='GET'&&$action==='track'){$s=$db->prepare('SELECT code,name AS client,service,description,channel,status,amount,created_at FROM requests WHERE code=?');$s->execute([strtoupper(trim((string)($_GET['code']??'')))]);$r=$s->fetch(PDO::FETCH_ASSOC);out($r?['ok'=>true,'request'=>$r]:['ok'=>false,'message'=>'Pedido não encontrado.'],$r?200:404);}
if($_SERVER['REQUEST_METHOD']==='POST'&&$action==='request'){$d=json_decode(file_get_contents('php://input')?:'{}',true)?:[];foreach(['name','phone','service'] as $f)if(trim((string)($d[$f]??''))==='')out(['ok'=>false,'message'=>'Preencha nome, telefone e serviço.'],422);$n=(int)$db->query('SELECT COALESCE(MAX(id),1090)+1 FROM requests')->fetchColumn();$s=$db->prepare('INSERT INTO requests(code,name,phone,service,description,channel,status) VALUES(?,?,?,?,?,?,?)');$s->execute(['CD-'.$n,trim($d['name']),trim($d['phone']),trim($d['service']),trim((string)($d['description']??'')),trim((string)($d['channel']??'Site')),'novo']);out(['ok'=>true,'code'=>'CD-'.$n]);}
out(['ok'=>false,'message'=>'Ação inválida.'],404);
